const ZadShare={getPageShareData(){const page=window.location.pathname.split("/").pop().replace(".html","")||"index";const url=window.location.href;const title=document.title||"زاد";const descriptions={index:"زاد — رفيقك الروحاني في أفضل أيام الدنيا",adhkar:"أذكار موثّقة من زاد — الصباح والمساء وأكثر","adhkar-categories":"كل الأذكار في مكان واحد — زاد",mushaf:"تابع ختمتك في زاد",takbeer:"سبّح وكبّر مع زاد",hasad:"حصاد عبادتي في زاد",arafah:"برنامج يوم عرفة — زاد",taqweem:"التقويم الإسلامي السنوي — زاد",fadael:"فضائل عشر ذي الحجة — زاد"};return{url:url,title:title,text:descriptions[page]||"اكتشف زاد — رفيقك في عشر ذي الحجة"}},async share(){const data=this.getPageShareData();if(navigator.share){try{await navigator.share({title:data.title,text:data.text,url:data.url});return}catch(e){if(e.name==="AbortError")return}}this.showShareSheet(data)},showShareSheet(data){if(document.getElementById("zad-share-sheet"))return;const enc=encodeURIComponent;const shareLinks=[{name:"واتساب",icon:"💬",url:`https://wa.me/?text=${enc(data.text+" "+data.url)}`},{name:"تيليجرام",icon:"✈️",url:`https://t.me/share/url?url=${enc(data.url)}&text=${enc(data.text)}`},{name:"تويتر / X",icon:"𝕏",url:`https://twitter.com/intent/tweet?text=${enc(data.text)}&url=${enc(data.url)}`},{name:"فيسبوك",icon:"📘",url:`https://www.facebook.com/sharer/sharer.php?u=${enc(data.url)}`}];const sheet=document.createElement("div");sheet.id="zad-share-sheet";sheet.className="zad-share-overlay";sheet.innerHTML=`\n      <div class="zad-share-panel">\n        <div class="zad-share-handle"></div>\n        <div class="zad-share-title">مشاركة هذه الصفحة</div>\n        <div class="zad-share-grid">\n          ${shareLinks.map(l=>`\n            <a href="${l.url}" target="_blank" rel="noopener" class="zad-share-item" onclick="window.ZadShare.close()">\n              <span class="zsi-icon">${l.icon}</span>\n              <span class="zsi-name">${l.name}</span>\n            </a>\n          `).join("")}\n          <button class="zad-share-item" onclick="window.ZadShare.copyLink()">\n            <span class="zsi-icon">🔗</span>\n            <span class="zsi-name">نسخ الرابط</span>\n          </button>\n        </div>\n        <button class="zad-share-cancel" onclick="window.ZadShare.close()">إلغاء</button>\n      </div>`;document.body.appendChild(sheet);requestAnimationFrame(()=>sheet.classList.add("open"));sheet.addEventListener("click",e=>{if(e.target===sheet)this.close()})},async copyLink(){const data=this.getPageShareData();try{await navigator.clipboard.writeText(data.url);if(typeof showToast==="function")showToast("🔗 تم نسخ الرابط")}catch{const ta=document.createElement("textarea");ta.value=data.url;document.body.appendChild(ta);ta.select();document.execCommand("copy");document.body.removeChild(ta);if(typeof showToast==="function")showToast("🔗 تم نسخ الرابط")}this.close()},close(){const sheet=document.getElementById("zad-share-sheet");if(sheet){sheet.classList.remove("open");setTimeout(()=>sheet.remove(),280)}},injectButton(){if(document.getElementById("zad-share-section"))return;const main=document.querySelector("main.main, #main-content, main, .main");if(!main)return;const section=document.createElement("div");section.id="zad-share-section";section.className="zad-share-section";section.innerHTML=`\n      <div class="zss-divider"></div>\n      <div class="zss-text">شارك هذه الصفحة مع أحبابك — الدالّ على الخير كفاعله</div>\n      <button id="zad-share-btn" class="zad-share-btn-full" aria-label="مشاركة الصفحة">\n        <span>📤</span><span>مشاركة الصفحة</span>\n      </button>`;main.appendChild(section);section.querySelector("#zad-share-btn").onclick=()=>this.share()},injectCSS(){if(document.getElementById("zad-share-css"))return;const s=document.createElement("style");s.id="zad-share-css";s.textContent=`\n      .zad-share-section { padding: 24px 16px 32px; text-align: center; }\n      .zss-divider { height: 1px; background: var(--border, #e5e5e5); margin-bottom: 20px; }\n      .zss-text { font-size: 13px; color: var(--muted, #888); margin-bottom: 14px; line-height: 1.6; }\n      .zad-share-btn-full { display: inline-flex; align-items: center; gap: 8px;\n        padding: 12px 28px; border-radius: 14px; border: 1.5px solid var(--zad-green-700, #1a5d47);\n        background: var(--card, #fff); color: var(--green-deep, #0e3b2e);\n        font-family: inherit; font-size: 15px; font-weight: 700; cursor: pointer;\n        min-height: 48px; transition: all .2s; }\n      .zad-share-btn-full:hover { background: var(--zad-green-900, #0e3b2e); color: #fff; border-color: var(--zad-green-900, #0e3b2e); }\n      .zad-share-btn-full:active { transform: scale(.97); }\n      .zad-share-overlay { position: fixed; inset: 0; background: rgba(0,0,0,.5);\n        z-index: 9600; display: flex; align-items: flex-end; justify-content: center;\n        opacity: 0; transition: opacity .28s; }\n      .zad-share-overlay.open { opacity: 1; }\n      .zad-share-panel { background: var(--card,#fff); width: 100%; max-width: 480px;\n        border-radius: 24px 24px 0 0; padding: 12px 20px 24px;\n        transform: translateY(100%); transition: transform .28s cubic-bezier(.4,0,.2,1); }\n      .zad-share-overlay.open .zad-share-panel { transform: translateY(0); }\n      .zad-share-handle { width: 40px; height: 4px; background: var(--border,#ddd);\n        border-radius: 2px; margin: 0 auto 16px; }\n      .zad-share-title { font-size: 17px; font-weight: 800; text-align: center; margin-bottom: 20px; }\n      .zad-share-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(72px, 1fr)); gap: 12px; margin-bottom: 16px; }\n      .zad-share-item { display: flex; flex-direction: column; align-items: center; gap: 6px;\n        padding: 12px 8px; border-radius: 14px; border: none; background: var(--sand,#faf9f6);\n        cursor: pointer; text-decoration: none; color: var(--ink,#222); font-family: inherit;\n        min-height: 72px; justify-content: center; transition: background .2s; }\n      .zad-share-item:hover { background: var(--border,#eee); }\n      .zsi-icon { font-size: 26px; }\n      .zsi-name { font-size: 12px; font-weight: 700; }\n      .zad-share-cancel { width: 100%; padding: 14px; border-radius: 14px; border: none;\n        background: var(--sand,#f0f0ec); font-family: inherit; font-size: 15px; font-weight: 700;\n        cursor: pointer; min-height: 44px; }\n      @media (prefers-reduced-motion: reduce) {\n        .zad-share-overlay, .zad-share-panel { transition: none !important; }\n      }\n    `;document.head.appendChild(s)},init(){this.injectCSS();this.injectButton()}};window.ZadShare=ZadShare;document.addEventListener("DOMContentLoaded",()=>{ZadShare.init();console.log("[ZadShare] ✅ زر النشر جاهز")});